def update(self, e=None, **f):
        """Override dict.update() to title-case keys."""
        if e is not None:
            if isinstance(e, dict):
                e = e.copy()
                for k in e:
                    if isinstance(e[k], dict):
                        e[k] = e[k].copy()
                        e[k] = self.__class__(e[k], title=True)
                    elif isinstance(e[k], list):
                        e[k] = self.__class__(e[k], title=True)
            elif isinstance(e, list):
                e = e.copy()
                for i, v in enumerate(e):
                    if isinstance(v, dict):
                        e[i] = e[i].copy()
                        e[i] = self.__class__(e[i], title=True)
                    elif isinstance(v, list):
                        e[i] = self.__class__(e[i], title=True)
            elif isinstance(e, (str, int)):
                e = e.copy()
            else:
                raise ValueError(f'Cannot update {type(e)}')

            return super(Dict, self).update(e)
        else:
            return super(Dict, self).update(**f)

